#!/usr/bin/env python3
"""Rigs for Trick or Treat House (g33): family (kid, sister, mom, dad) + costumes (ghost cat pumpkin vampire robot pirate dino).
All viewBox 100x120, parts legB legF torso head arm. Original art. Then add to SETS in build-art.cjs and run node art/build-art.cjs."""
import os
here = os.path.dirname(os.path.abspath(__file__)); OL = '#15171d'
def grad(i, a, b, v=False): return f'<linearGradient id="{i}" x1="0" y1="0" x2="{0 if v else 1}" y2="1"><stop offset="0" stop-color="{a}"/><stop offset="1" stop-color="{b}"/></linearGradient>'
def legs(c, sh, y0=76, w=13):
    return (f'<g data-p="legB"><path d="M36 {y0} l-2 {100-y0} l{w} 1 l3 -{101-y0}z" fill="{c}"/><path d="M30 101 q-2 0 -2 5 q0 5 8 5 h14 q4 0 4 -5 l-2 -5z" fill="{sh}"/></g>'
            f'<g data-p="legF"><path d="M54 {y0} l3 {101-y0} l{w} -1 l-4 -{100-y0}z" fill="{c}"/><path d="M54 102 q-4 0 -4 5 q0 5 8 5 h16 q5 0 5 -5 l-2 -5z" fill="{sh}"/></g>')
def eyes(dx=0, col='#fff', pup=OL, r=5.5):
    return (f'<circle cx="{40+dx}" cy="36" r="{r}" fill="{col}"/><circle cx="{60+dx}" cy="36" r="{r}" fill="{col}"/><circle cx="{41.5+dx}" cy="37" r="2.6" fill="{pup}" stroke="none"/><circle cx="{61.5+dx}" cy="37" r="2.6" fill="{pup}" stroke="none"/>')
def smile(y=47, w=8): return f'<path d="M{50-w} {y} q{w} 7 {2*w} 0" fill="none" stroke-width="2.6"/>'
BUCKET = '<g><path d="M80 60 h20 l-3 20 h-14z" fill="#ff9a1a"/><path d="M80 60 h20 l-.5 4 h-19z" fill="#ffb84a" stroke="none"/><path d="M82 59 q8 -14 16 0" fill="none" stroke="#7a4a10" stroke-width="2"/><circle cx="88" cy="68" r="2" fill="#2a1a08" stroke="none"/><circle cx="94" cy="72" r="1.6" fill="#e04040" stroke="none"/></g>'
def arm(sl, hand, prop='', x=66, y=52): return f'<g data-p="arm"><path d="M{x} {y} q14 0 20 8 l-4 7 q-9 -4 -18 -3z" fill="{sl}"/><circle cx="{x+20}" cy="{y+11}" r="5.5" fill="{hand}"/>{prop}</g>'
SK = '#f2c79a'
def tor(path, fill, extra=''): return f'<g data-p="torso"><path d="{path}" fill="{fill}"/>{extra}</g>'
TORSO = 'M30 48 q-4 0 -4 8 l2 26 q22 8 44 0 l2 -26 q0 -8 -4 -8z'
def svg(defs, body): return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 120" width="400" height="480"><defs>{defs}</defs><g stroke="{OL}" stroke-width="3.2" stroke-linejoin="round" stroke-linecap="round">{body}</g></svg>'
def human(sk, hair, shirt, shirt2, pants, shoe, hairstyle, extra_head='', prop='', skirt=False, hairback=''):
    d = grad('s', shirt, shirt2)
    lg = legs(pants, shoe)
    if skirt: lg = legs(sk, shoe, 86, 11)
    t = tor(TORSO, 'url(#s)', f'<path d="M26 82 q24 12 48 0 l2 10 q-26 10 -52 0z" fill="{pants}" stroke="none" opacity=".0"/>' + ('<path d="M24 80 l-6 18 q32 10 64 0 l-6 -18z" fill="'+pants+'"/>' if skirt else ''))
    h = f'<g data-p="head">{hairback}<ellipse cx="50" cy="32" rx="21" ry="19" fill="{sk}"/>{hairstyle}{eyes()}{smile()}<circle cx="31" cy="42" r="3" fill="#ff8a8a" stroke="none" opacity=".55"/><circle cx="69" cy="42" r="3" fill="#ff8a8a" stroke="none" opacity=".55"/>{extra_head}</g>'
    return svg(d, lg + t + h + arm(shirt2, sk, prop))
CANDY = '<g><circle cx="90" cy="62" r="5" fill="#ff5a8a"/><path d="M82 62 l-5 -4 v8z M98 62 l5 -4 v8z" fill="#ffd84a"/></g>'
R = {}
# --- family
R['kid'] = human(SK, '#7a4a20', '#6ac04a', '#2e7a2a', '#3a5aa8', '#e8e0d0', '<path d="M29 30 q0 -20 21 -20 q21 0 21 20 q-8 -8 -21 -8 q-13 0 -21 8z" fill="#7a4a20"/>', extra_head='<path d="M28 24 q22 -26 44 0 l2 6 q-24 -16 -48 0z" fill="#e85a2a"/><rect x="26" y="26" width="48" height="5" rx="2" fill="#c03a10"/><circle cx="50" cy="9" r="4" fill="#ffd84a"/>', prop=CANDY)
R['sister'] = human('#f0c090', '#e8a030', '#ff7ab8', '#b82a78', '#7a5ac8', '#fff', '<path d="M29 32 q-2 -22 21 -22 q23 0 21 22 q-8 -10 -21 -10 q-13 0 -21 10z" fill="#e8a030"/>', hairback='<path d="M26 28 q-6 30 4 36 l6 -10z M74 28 q6 30 -4 36 l-6 -10z" fill="#e8a030"/>', extra_head='<path d="M62 14 q10 -6 14 2 q-4 8 -14 4z M62 14 q-8 -8 -14 -2 q4 8 14 4z" fill="#ff4a9a"/>', skirt=True, prop='<g><path d="M82 50 l12 -14 M82 50 l-3 -16" stroke="#7a4a20" stroke-width="3" fill="none"/><path d="M79 34 q8 -4 15 2" stroke="#ffd84a" stroke-width="2" fill="none"/><circle cx="88" cy="66" r="4.5" fill="#ff5a8a"/></g>')
R['mom'] = human('#e8b88a', '#4a2a18', '#f2f2f2', '#9ab0d8', '#3a4a6a', '#6a3a28', '<path d="M28 32 q-2 -22 22 -22 q24 0 22 22 q-10 -12 -22 -12 q-12 0 -22 12z" fill="#4a2a18"/>', hairback='<path d="M26 26 q-8 34 6 44 l8 -14z M74 26 q8 34 -6 44 l-8 -14z" fill="#4a2a18"/>', extra_head='<path d="M40 48 q10 8 20 0" fill="none" stroke="#c03a3a" stroke-width="2.4"/>', prop='<g><rect x="82" y="56" width="16" height="12" rx="3" fill="#ffd84a"/><circle cx="88" cy="52" r="3.4" fill="#ff5a8a"/><circle cx="94" cy="52" r="3.4" fill="#6ae8ff"/></g>')
R['dad'] = human('#e2b080', '#2a1a10', '#b84a2a', '#6a1a10', '#3a3a48', '#2a2a30', '<path d="M28 30 q0 -22 22 -22 q22 0 22 22 q-4 -8 -22 -8 q-18 0 -22 8z" fill="#2a1a10"/>', extra_head='<path d="M38 46 q12 6 24 0 q-4 -4 -12 -3 q-8 -1 -12 3z" fill="#2a1a10" stroke="none"/><path d="M36 28 h28" stroke="#15171d" stroke-width="2"/><rect x="34" y="31" width="12" height="9" rx="3" fill="none" stroke="#15171d" stroke-width="2.4"/><rect x="54" y="31" width="12" height="9" rx="3" fill="none" stroke="#15171d" stroke-width="2.4"/>', prop='<g><rect x="78" y="52" width="26" height="14" rx="5" fill="#5a5a6a"/><rect x="98" y="50" width="8" height="18" rx="3" fill="#3a3a48"/><circle cx="84" cy="59" r="3" fill="#ffd84a" stroke="none"/></g>')
R['baby'] = human('#f6d0a8', '#e8b870', '#bfe4ff', '#6aa8e8', '#fff', '#fff', '<path d="M32 26 q18 -10 36 0 q-4 -4 -18 -4 q-14 0 -18 4z" fill="#e8b870"/>', extra_head='<path d="M27 34 q-6 -26 23 -26 q29 0 23 26 q-8 -14 -23 -14 q-15 0 -23 14z" fill="#ffb8d8"/><circle cx="50" cy="9" r="5" fill="#fff"/><path d="M30 44 q20 12 40 0" fill="none" stroke="#e86aa0" stroke-width="2"/>', prop='<g><circle cx="88" cy="64" r="5" fill="#ffd84a"/><path d="M80 64 l-5 -4 v8z M96 64 l5 -4 v8z" fill="#ff5a8a"/></g>')
# --- costumes
def costume(torso_fill, torso2, head_svg, pants, shoe, prop_sleeve, extra_torso='', hand=SK, headback='', legsvg=None, torso_path=TORSO):
    d = grad('s', torso_fill, torso2)
    lg = legsvg or legs(pants, shoe)
    t = tor(torso_path, 'url(#s)', extra_torso)
    return svg(d, lg + t + f'<g data-p="head">{headback}{head_svg}</g>' + arm(prop_sleeve, hand, BUCKET))
def face(dx=0, col='#fff'): return eyes(dx, col) + smile()
R['ghost'] = costume('#ffffff', '#c8d0e8', '<path d="M24 36 q0 -28 26 -28 q26 0 26 28 v12 q-5 6 -10 0 q-5 6 -10 0 q-5 6 -10 0 q-5 6 -10 0 q-5 6 -10 0z" fill="url(#s)"/>' + eyes(0, '#15171d', '#fff', 5) + '<ellipse cx="50" cy="46" rx="4.5" ry="5.5" fill="#15171d" stroke="none"/>', '#f8f8ff', '#c8d0e8', '#e8ecf8', torso_path='M24 46 q0 -4 6 -4 h40 q6 0 6 4 l4 40 q-30 10 -60 0z', legsvg=legs('#c8d0e8', '#9aa6c8', 90, 11), extra_torso='<path d="M26 82 q6 8 12 0 q6 8 12 0 q6 8 12 0 q6 8 12 0" fill="none" stroke-width="2.4"/>', hand='#e8ecf8')
R['cat'] = costume('#7a7a8a', '#3a3a4a', '<path d="M30 20 l-6 -18 l16 8z M70 20 l6 -18 l-16 8z" fill="#3a3a4a"/><path d="M30 14 l-2 -8 l8 4z M70 14 l2 -8 l-8 4z" fill="#ff9ab8" stroke="none"/><ellipse cx="50" cy="32" rx="21" ry="19" fill="#4a4a5a"/><path d="M50 14 v8 M42 15 v6 M58 15 v6" stroke="#2a2a38" stroke-width="3" fill="none"/>' + eyes(0, '#ffe65a', OL, 5.5) + '<path d="M47 42 h6 l-3 3z" fill="#ff7a9a" stroke-width="1.6"/><path d="M50 45 v3 M44 49 q6 4 12 0" fill="none" stroke-width="2.2"/><path d="M26 42 l-10 -2 M26 46 l-10 3 M74 42 l10 -2 M74 46 l10 3" stroke-width="1.6" fill="none"/>', '#3a3a4a', '#15171d', '#4a4a5a', extra_torso='<path d="M36 52 v26 M50 52 v28 M64 52 v26" stroke="#2a2a38" stroke-width="3" fill="none"/>', headback='<path d="M24 80 q-22 -4 -16 -30 q4 -12 14 -4" fill="none" stroke="#4a4a5a" stroke-width="7"/>', hand='#4a4a5a')
R['pumpkin'] = costume('#ff8a1a', '#c04a08', '<ellipse cx="50" cy="30" rx="30" ry="25" fill="#ff8a1a"/><path d="M50 6 q-4 28 0 50 M32 9 q-12 20 0 44 M68 9 q12 20 0 44" fill="none" stroke="#c04a08" stroke-width="2.4"/><rect x="46" y="-2" width="8" height="12" rx="3" fill="#4a8a2a"/><path d="M38 22 l4 10 h-8z M62 22 l4 10 h-8z" fill="#ffe65a"/><path d="M36 42 h28 l-4 8 l-5 -4 l-5 5 l-5 -5 l-5 4z" fill="#ffe65a"/>', '#4a2a10', '#2a1a10', '#ff8a1a', extra_torso='<ellipse cx="50" cy="66" rx="28" ry="24" fill="#ff8a1a"/><path d="M50 44 q-4 22 0 44 M34 48 q-8 18 0 38 M66 48 q8 18 0 38" fill="none" stroke="#c04a08" stroke-width="2.4"/>', torso_path='M24 66 q0 -22 26 -22 q26 0 26 22 q0 22 -26 22 q-26 0 -26 -22z', hand='#ff8a1a')
R['vampire'] = costume('#2a2a3a', '#101018', '<ellipse cx="50" cy="32" rx="21" ry="19" fill="#e8e2f0"/><path d="M29 30 q2 -22 21 -22 q19 0 21 22 q-6 -9 -12 -9 l-9 8 l-9 -8 q-6 0 -12 9z" fill="#15151e"/>' + eyes(0, '#fff', '#e02020') + '<path d="M42 46 q8 5 16 0" fill="#7a1010" stroke-width="2.4"/><path d="M44 46 l2 6 l2 -5 M52 47 l2 5 l2 -6" fill="#fff" stroke-width="1.4"/>', '#1a1a24', '#15171d', '#2a2a3a', headback='<path d="M22 44 q-14 40 -4 62 l30 6 l30 -6 q10 -22 -4 -62z" fill="#a01028"/><path d="M26 46 q-10 36 -2 54" fill="none" stroke="#e03048" stroke-width="2.4"/>', extra_torso='<path d="M40 48 l10 18 l10 -18z" fill="#f4f0f8"/><rect x="47" y="64" width="6" height="14" fill="#a01028" stroke="none"/><path d="M26 48 l24 10 l24 -10 l-4 -4 l-20 8 l-20 -8z" fill="#c01838"/>', hand='#e8e2f0')
R['robot'] = costume('#b8c4d4', '#6a7890', '<rect x="26" y="14" width="48" height="38" rx="8" fill="url(#s)"/><rect x="48" y="2" width="4" height="12" fill="#6a7890"/><circle cx="50" cy="2" r="4" fill="#ff4a4a"/><rect x="31" y="26" width="38" height="14" rx="4" fill="#15171d"/><rect x="34" y="29" width="10" height="8" rx="2" fill="#5aeaff" stroke="none"/><rect x="56" y="29" width="10" height="8" rx="2" fill="#5aeaff" stroke="none"/><path d="M38 46 h24" stroke-width="3"/><rect x="20" y="28" width="6" height="12" rx="2" fill="#6a7890"/><rect x="74" y="28" width="6" height="12" rx="2" fill="#6a7890"/>', '#5a6880', '#2a3040', '#8a98b0', torso_path='M26 48 q-2 0 -2 6 l2 28 q24 8 48 0 l2 -28 q0 -6 -2 -6z', extra_torso='<rect x="34" y="56" width="32" height="20" rx="3" fill="#2a3040"/><circle cx="42" cy="66" r="4" fill="#ffd84a" stroke="none"/><circle cx="56" cy="66" r="4" fill="#5aeaff" stroke="none"/><path d="M34 58 h32" stroke="#6a7890" stroke-width="2"/>', hand='#6a7890')
R['pirate'] = costume('#e8e0d0', '#b0a488', '<ellipse cx="50" cy="32" rx="21" ry="19" fill="#f2c79a"/><path d="M26 22 q24 -26 48 0 q-6 -6 -24 -6 q-18 0 -24 6z" fill="#15171d"/><path d="M27 20 q23 -22 46 0 l2 6 h-50z" fill="#15171d"/><circle cx="50" cy="16" r="4" fill="#fff" stroke="none"/><path d="M47 14 l6 4 M53 14 l-6 4" stroke="#15171d" stroke-width="1.6"/><rect x="31" y="26" width="38" height="4" fill="#d03030" stroke="none"/><circle cx="40" cy="37" r="5.5" fill="#fff"/><circle cx="41.5" cy="38" r="2.6" fill="#15171d" stroke="none"/><path d="M52 31 L70 24" stroke="#15171d" stroke-width="2.6"/><circle cx="61" cy="36" r="6" fill="#15171d"/>' + smile(48) + '<path d="M30 48 q20 14 40 0 q-4 10 -20 10 q-16 0 -20 -10z" fill="#5a2a10" stroke="none" opacity=".0"/>', '#4a3a6a', '#2a1a10', '#e8e0d0', extra_torso='<path d="M30 48 l20 12 l20 -12" fill="none" stroke-width="2.4"/><rect x="28" y="70" width="44" height="7" fill="#7a3a18"/><rect x="46" y="69" width="8" height="9" rx="1" fill="#ffd84a"/><path d="M30 50 h40 M30 58 h40" stroke="#d03030" stroke-width="3" stroke-opacity=".8" fill="none"/>', hand='#f2c79a')
R['dino'] = costume('#6ac84a', '#2e7a2a', '<path d="M18 20 q-4 -20 14 -16 q6 -10 18 -8 q12 -2 18 8 q18 -4 14 16 q4 24 -8 36 q-24 10 -48 0 q-12 -12 -8 -36z" fill="url(#s)"/><path d="M34 6 l6 -9 l6 9 M50 6 l6 -11 l6 11" fill="#ff9a2a"/><circle cx="38" cy="26" r="7" fill="#ffe65a"/><circle cx="62" cy="26" r="7" fill="#ffe65a"/><ellipse cx="38" cy="27" rx="2" ry="5" fill="#15171d" stroke="none"/><ellipse cx="62" cy="27" rx="2" ry="5" fill="#15171d" stroke="none"/><path d="M26 44 q24 12 48 0 l-3 8 q-21 8 -42 0z" fill="#e8f8d0"/><path d="M32 46 l3 6 l3 -5 M44 49 l3 6 l3 -6 M56 48 l3 5 l3 -6" fill="#fff" stroke-width="1.4"/><circle cx="44" cy="36" r="1.6" fill="#15171d" stroke="none"/><circle cx="56" cy="36" r="1.6" fill="#15171d" stroke="none"/>', '#2e7a2a', '#1a4a1a', '#4aa83a', extra_torso='<path d="M30 56 q20 -8 40 0 M30 70 q20 -8 40 0" stroke="#2e7a2a" stroke-width="3" fill="none"/><path d="M40 58 l-4 -8 M50 56 l0 -10 M60 58 l4 -8" fill="#ff9a2a" stroke="#c06a10"/>', headback='<path d="M24 82 q-30 8 -22 -14 q8 8 28 -4z" fill="#4aa83a"/>', hand='#4aa83a', torso_path='M26 46 q-4 0 -4 10 l2 28 q26 8 52 0 l2 -28 q0 -10 -4 -10z')
for k, s in R.items(): open(f'{here}/hw_{k}_rig.svg', 'w').write(s)
print('wrote', ', '.join(R))
